from html import escape

def render_companies(page, interactive_map):
    companies = [
        ('01','MDHI','Taicang','The strength behind the structure.','Structural steel','MDHI fabricates structural steel for buildings, infrastructure and industrial projects, with detailing, fabrication, coatings and assembly supported by port-oriented delivery.','companies-mdhi.webp','MDHI manufacturing operations','169 Longjiang Road, Taicang Port Development Zone, Taicang','Taicang Port access for domestic and international project delivery.'),
        ('02','MMEC','Zhangjiagang','Complex plants. Connected thinking.','Structural steel & modular plants','MMEC brings structural fabrication, module assembly and logistics together, supporting project requirements from workshop fabrication to port load-out.','companies-mmec.webp','MMEC manufacturing operations','2669 Yanjiang Road, Daxin Town, Zhangjiagang','SPMT transport, port-side storage and vessel load-out via Gangxin terminal.'),
        ('03','MEEM','Zhangjiagang','Precision for energy.','HRSG pressure parts & air-cooled heat exchangers','MEEM manufactures HRSG pressure parts and air-cooled heat exchanger equipment for power and process applications, with packaging and delivery coordinated for each project.','companies-meem.webp','MEEM manufacturing operations','1 Duanshan Road, Deji Subdistrict, Zhangjiagang','Zhangjiagang river port access for energy equipment shipment.')
    ]
    content = '''<section class="cl-hero"><div class="cl-hero-copy"><p class="cl-eyebrow">Companies &amp; Locations</p><h1>Specialist expertise.<br>Shared ambition.</h1><p class="cl-intro">Three specialist companies. A connected footprint along the Yangtze. Explore our manufacturing capabilities and the locations behind them.</p><a class="cl-link" href="#our-companies">Explore our companies <span aria-hidden="true">→</span></a></div><div class="cl-hero-image"><img src="../assets/images/companies-locations-hero.webp" alt="Illustration of connections across the Yangtze River region" fetchpriority="high"><span>Jiangsu · China</span></div></section>
<nav class="cl-index" aria-label="On this page"><a href="#company-mdhi"><span>01</span> MDHI</a><a href="#company-mmec"><span>02</span> MMEC</a><a href="#company-meem"><span>03</span> MEEM</a><a href="#our-locations">Our locations <span aria-hidden="true">↓</span></a></nav>
<section class="cl-companies" id="our-companies" aria-label="Our manufacturing companies">'''
    for num,code,city,title,scope,desc,img,alt,address,logistics in companies:
        slug=code.lower()
        content += f'''<article class="cl-company" id="company-{slug}"><div class="cl-number"><span>{num}</span><strong>{code}</strong><small>{city}</small></div><figure class="cl-photo"><img src="../assets/images/{img}" alt="{escape(alt)}" loading="lazy" decoding="async"></figure><div class="cl-company-copy"><h2>{title}</h2><p class="cl-scope">{escape(scope)}</p><p>{desc}</p><div class="cl-location"><p><b>Location</b>{address}</p><p><b>Logistics</b>{logistics}</p></div><div class="cl-links"><a class="cl-link" href="../{slug}/index.html">View {code} profile <span aria-hidden="true">→</span></a><a class="cl-link" href="#our-locations" data-company-location="{slug}">{city} location <span aria-hidden="true">↗</span></a></div></div></article>'''
    content += '''</section><section class="cl-network" id="our-locations"><div class="cl-network-heading"><div><p class="cl-eyebrow">Our locations</p><h2>Rooted on the Yangtze.<br>Connected to your project.</h2></div><p>Our manufacturing companies are based in Taicang and Zhangjiagang, with access to river ports and inland transport. Our Shanghai engineering center supports engineering and commercial coordination.</p></div><div class="cl-map-wrap">'''
    content += interactive_map(1, 'full')
    content += '''</div></section><section class="cl-enquiry"><div><p class="cl-eyebrow">Let's build together</p><h2>Find your manufacturing partner.</h2></div><a class="button button-gold" href="../contact/index.html">Start an enquiry <span aria-hidden="true">→</span></a></section>'''
    return page('Companies & Locations | Modern Group',1,'Companies & Locations','','','',content,'Explore MDHI, MMEC and MEEM: three specialist manufacturing companies in Taicang and Zhangjiagang, connected with Shanghai and Yangtze River ports.')
